class Push::Notification
  attr_reader :notification

  def initialize(notification = nil, **attributes)
    @notification = notification
    @attributes = attributes
  end

  def title
    @attributes[:title] || notification&.push_title
  end

  def body
    @attributes[:body] || notification&.push_body
  end

  def url
    @attributes[:url] || notification&.push_url
  end

  def to_h
    { title: title, body: body, url: url }
  end
  alias_method :as_json, :to_h

  def to_json(*)
    to_h.to_json
  end
end
